// Run with the workspace Electron executable, an installed app.asar path, and
// the directory generated by prepare-psd-host-tests.mjs. All state is isolated.
const {app,BrowserWindow,protocol,ipcMain}=require('electron');
const fs=require('node:fs'),originalFs=require('original-fs'),assert=require('node:assert/strict');
const {join,resolve,relative,isAbsolute,extname}=require('node:path');
const {createHash,randomBytes}=require('node:crypto');
if(!process.argv[2]||!process.argv[3])throw Error('Supply installed app.asar and Photoshop QA directory.');
const archive=resolve(process.argv[2]),directory=resolve(process.argv[3]);
const host=JSON.parse(fs.readFileSync(join(directory,'host-report.json'),'utf8').replace(/^\uFEFF/,''));
assert.equal(host.application,'Adobe Photoshop');assert.equal(host.complete,true);
assert.deepEqual(host.cases.map(c=>c.name),['PSD-QA-Clouds','PSD-QA-Solarize']);
const profile=fs.mkdtempSync(join(directory,'installed-runtime-'));app.setPath('userData',join(profile,'electron'));
protocol.registerSchemesAsPrivileged([{scheme:'broadcastcg',privileges:{standard:true,secure:true,supportFetchAPI:true,corsEnabled:true}}]);
const outputFile=join(profile,'verification.json'),checks=[];let service,sessions,win,token,ack;
const hash=createHash('sha256').update(originalFs.readFileSync(archive)).digest('hex');
const finish=(ok,error)=>{try{sessions?.clear();service?.close();win?.destroy();}catch{}const result={ok,error:error?.message,stack:error?.stack,archive,archiveSHA256:hash,version:require(join(archive,'package.json')).version,adobeVersion:host.version,profile,checks,time:new Date().toISOString()};fs.writeFileSync(outputFile,JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));app.exit(ok?0:1);};
app.whenReady().then(async()=>{
 const {createLocalService}=require(join(archive,'app/service.cjs')),{createPsdSessions}=require(join(archive,'psd-session.cjs'));
 const password=randomBytes(24).toString('hex'),credentials={username:'psd_plugin_qa',password};
 const create=()=>createLocalService({directory:join(profile,'data')});service=create();({token}=await service.auth.setup(credentials));
 const api=async(path,body)=>{const r=await service.handle(new Request('broadcastcg://app'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),{token});const value=await r.json();assert.equal(r.status,200,JSON.stringify(value));return value;};
 let project={version:1,id:'psd-host-qualification',name:'Photoshop plugin qualification',scenes:[{id:'empty',name:'Empty',width:640,height:360,duration:1,layers:[]}],panels:[{id:'panel',name:'Control panel',type:'custom',columns:3,controls:[]}],variables:{},sources:[],bindings:[],players:[]},revision=1;
 await api('/api/projects',{project,revision:0});
 sessions=createPsdSessions({workerPath:join(archive,'app/psd-worker.cjs'),authorize:t=>{service.authorize(t,'templates.import');service.authorize(t,'graphics.create');},commit:(d,o,t)=>service.importPsd(d,o,t)});
 const root=join(archive,'app/renderer'),mime={'.html':'text/html','.css':'text/css','.js':'text/javascript','.png':'image/png','.svg':'image/svg+xml'};
 protocol.handle('broadcastcg',async request=>{const url=new URL(request.url);if(url.hostname!=='app')return new Response('Forbidden',{status:403});if(url.pathname.startsWith('/api/'))return service.handle(request,service.outputContext);const target=resolve(root,'.'+(url.pathname==='/output'?'/index.html':url.pathname)),rel=relative(root,target);if(!rel||rel.startsWith('..')||isAbsolute(rel))return new Response('Forbidden',{status:403});try{return new Response(fs.readFileSync(target),{headers:{'Content-Type':mime[extname(target)]||'application/octet-stream'}});}catch{return new Response('Not found',{status:404});}});
 win=new BrowserWindow({width:640,height:360,useContentSize:true,show:false,webPreferences:{preload:join(archive,'preload.cjs'),sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});
 win.webContents.session.setPermissionRequestHandler((_wc,_p,callback)=>callback(false));
 win.webContents.session.webRequest.onBeforeRequest({urls:['http://*/*','https://*/*']},(_d,callback)=>callback({cancel:true}));
 ipcMain.on('broadcastcg:rendered',(event,revision)=>{if(event.sender===win.webContents)ack=revision;});
 await win.loadURL('broadcastcg://app/output');
 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 async function rendered(scene,label,reference){
   const program=await api('/api/program',{projectId:project.id,scene,variables:{},mode:'show'});win.webContents.send('broadcastcg:program',program);
   const deadline=Date.now()+5000;while(ack!==program.revision&&Date.now()<deadline)await sleep(30);assert.equal(ack,program.revision,'Output must acknowledge '+label);
   const ref='data:image/png;base64,'+fs.readFileSync(join(directory,reference)).toString('base64');
   const difference=await win.webContents.executeJavaScript(`(async()=>{
    const svg=document.querySelector('svg.graphic').cloneNode(true);svg.setAttribute('width','640');svg.setAttribute('height','360');
    for(const node of svg.querySelectorAll('image')){const response=await fetch(node.getAttribute('href'));if(!response.ok)throw Error('Output image unavailable');const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});node.setAttribute('href',data);}
    const actualImage=new Image(),expectedImage=new Image();actualImage.src='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(new XMLSerializer().serializeToString(svg))));expectedImage.src=${JSON.stringify(ref)};await Promise.all([actualImage.decode(),expectedImage.decode()]);
    const c=document.createElement('canvas');c.width=640;c.height=360;const ctx=c.getContext('2d');ctx.drawImage(actualImage,0,0);const actual=ctx.getImageData(0,0,640,360).data;ctx.clearRect(0,0,640,360);ctx.drawImage(expectedImage,0,0);const expected=ctx.getImageData(0,0,640,360).data;let mismatches=0,maxError=0;for(let i=0;i<actual.length;i++){const e=Math.abs(actual[i]-expected[i]);if(e)mismatches++;maxError=Math.max(maxError,e);}return{mismatches,maxError};
   })()`);
   assert.equal(difference.mismatches,0,label+': '+JSON.stringify(difference));
   fs.writeFileSync(join(profile,label+'.png'),(await win.webContents.capturePage()).toPNG());checks.push(label+': output acknowledged; native SVG raster matches Photoshop PNG exactly');
 }
 for(const c of host.cases){
  assert.equal(c.file,c.name+'.psd');assert.equal(c.reference,c.name+'.png');
  for(const mode of ['pixels','composite']){
   const prior=await api('/api/program'),draft=await sessions.prepare(join(directory,c.file),token);
   const saved=sessions.finish({id:draft.id,projectId:project.id,revision,mode,fonts:{},fontStatus:'checked',missingFonts:[]},token);project=saved.project;revision=saved.revision;
   assert.deepEqual(await api('/api/program'),prior,'Import must not publish');const scene=project.scenes.at(-1);assert.equal(scene.layers.length,1);assert.equal(scene.layers[0].type,'image');
   await rendered(scene,c.name+'-'+mode,c.reference);
  }
 }
 const restored=service.importProject(service.inspectImport(service.exportProject(project,token),token),token);assert.equal(restored.scenes.length,5);assert.notEqual(restored.scenes[1].layers[0].src,project.scenes[1].layers[0].src);
 for(let i=1;i<restored.scenes.length;i++){const response=await service.handle(new Request('broadcastcg://app'+restored.scenes[i].layers[0].src),{token});assert.equal(response.status,200);}
 checks.push('Complete project export/import retains all four plugin-artwork scenes and remaps embedded images');
 sessions.clear();service.close();service=create();({token}=await service.auth.login(credentials));const saved=await api('/api/projects/'+project.id);assert.equal(saved.project.scenes.length,5);assert.equal(service.diagnostics().database,'ok');
 await rendered(saved.project.scenes[1],'PSD-QA-Clouds-after-restart','PSD-QA-Clouds.png');checks.push('Isolated installed service restart preserves scenes, artwork and database integrity');
 finish(true);
}).catch(error=>finish(false,error));
